    }
    if let item = lodPitchThreshold {
      raw.fields |= MLN_MAP_TILE_OPTION_LOD_PITCH_THRESHOLD.rawValue; raw
        .lod_pitch_threshold = item
    }
    if let item = lodZoomShift {
