  public var frustumOffset: EdgeInsets?
  public init(
    northOrientation: NorthOrientation? = nil,
    constrainMode: ConstrainMode? = nil,
    viewportMode: ViewportMode? = nil,
    frustumOffset: EdgeInsets? = nil
  ) {
